const guardFor = (mode) =>
  `\n\nOutput rules: return only the words to be spoken aloud, with no headings, labels, markdown, or stage directions. Use only facts present in the data; if something is not in the data, leave it out. ${EXTRAS[mode]} Stay under ${WORD_LIMITS[mode]} words and finish on a complete sentence.`;

/* ---------- Helpers ---------- */
const pad = (n) => String(n).padStart(2, "0");
const ymd = (d) => `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const toInput = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const fromInput = (s) => { const [y, m, dd] = s.split("-").map(Number); return new Date(y, m - 1, dd); };
const fmtShort = (d) => d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
const fmtLong = (d) => d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
const fmtTime = (s) => (!isFinite(s) || s < 0 ? "0:00" : `${Math.floor(s / 60)}:${pad(Math.floor(s % 60))}`);
const teamKey = (sport, abbr) => `${sport}:${abbr}`;
const fallbackLogo = (sport, abbr) => `https://a.espncdn.com/i/teamlogos/${sport}/500/${String(abbr).toLowerCase()}.png`;
// NFL weeks run Tuesday to Monday, so a week never mixes in the previous Monday night game.
const nflWeekStart = (d) => addDays(d, -((d.getDay() - 2 + 7) % 7));
const windowDays = (sport, anchor, span) => span === 1 ? [anchor]
  : sport === "nfl" ? Array.from({ length: 7 }, (_, i) => addDays(nflWeekStart(anchor), i))
  : Array.from({ length: span }, (_, i) => addDays(anchor, -i));
const windowLabel = (tab, anchor) => {
  if (tab === "nfl") { const st = nflWeekStart(anchor); return `${fmtShort(st)} to ${fmtShort(addDays(st, 6))}`; }
  if (tab === "mine") return `${fmtShort(addDays(anchor, -6))} to ${fmtShort(anchor)}`;
  return fmtLong(anchor);
};
const scoreOf = (s) => (s && typeof s === "object" ? s.displayValue ?? s.value : s);

const spanFor = (sport, tab) => (tab === "mine" || sport === "nfl" ? 7 : 1);
const stepFor = (tab) => (tab === "nfl" || tab === "mine" ? 7 : 1);

/* ---------- Storage: small data in localStorage, audio files in IndexedDB ---------- */
const store = {
  async get(k) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : null; } catch { return null; } },
  async set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch (e) { console.error("storage set", e); return false; } },
  async del(k) { try { localStorage.removeItem(k); } catch { /* ignore */ } },
};
const openAudioDB = () => new Promise((res, rej) => {
  const r = indexedDB.open("replay-audio", 1);
  r.onupgradeneeded = () => r.result.createObjectStore("audio");
  r.onsuccess = () => res(r.result);
  r.onerror = () => rej(r.error);
});
const audioDB = {
  async put(id, blob) {
    try {
      const db = await openAudioDB();
      return await new Promise((res) => { const t = db.transaction("audio", "readwrite"); t.objectStore("audio").put(blob, id); t.oncomplete = () => res(true); t.onerror = () => res(false); });
    } catch { return false; }
  },
  async get(id) {
    try {
      const db = await openAudioDB();
      return await new Promise((res) => { const q = db.transaction("audio").objectStore("audio").get(id); q.onsuccess = () => res(q.result || null); q.onerror = () => res(null); });
    } catch { return null; }
  },
  async del(id) {
    try { const db = await openAudioDB(); db.transaction("audio", "readwrite").objectStore("audio").delete(id); } catch { /* ignore */ }
  },
};

/* ==========================================================================
   LAYER 1 — ESPN data
   ========================================================================== */
function normalizeEvent(ev, sport) {
  const comp = ev.competitions && ev.competitions[0];
  if (!comp) return null;
  const teams = (comp.competitors || []).map((c) => ({
    id: c.team.id,
    abbr: c.team.abbreviation,
    name: c.team.displayName,
    logo: c.team.logo,
    score: c.score,
    homeAway: c.homeAway,
    winner: !!c.winner,
    record: c.records && c.records[0] && c.records[0].summary,
    leaders: (c.leaders || []).slice(0, 3).map((l) => ({
      category: l.displayName || l.name,
      player: l.leaders && l.leaders[0] && l.leaders[0].athlete && l.leaders[0].athlete.displayName,
      stat: l.leaders && l.leaders[0] && l.leaders[0].displayValue,
    })).filter((l) => l.player),
  }));
  teams.sort((a, b) => (a.homeAway === "away" ? -1 : 1) - (b.homeAway === "away" ? -1 : 1));
  const h = comp.headlines && comp.headlines[0];
  return {
    id: `${sport}-${ev.id}`,
    eventId: ev.id,
    sport,
    date: ev.date,
    state: ev.status.type.state, // pre | in | post
    detail: ev.status.type.shortDetail,
    teams,
    note: h ? h.description || h.shortLinkText : null,
    venue: comp.venue && comp.venue.fullName,
  };
}

async function fetchDay(sport, date) {
  const res = await fetch(`${ESPN}${SPORTS[sport].path}/scoreboard?dates=${ymd(date)}`);
  if (!res.ok) throw new Error(`ESPN returned ${res.status} for ${SPORTS[sport].label}`);
  const j = await res.json();
  return (j.events || []).map((e) => {
    const g = normalizeEvent(e, sport);
    if (g) g.week = j.week && j.week.number;
    return g;
  }).filter(Boolean);
}

// A multi-day window is just several single-day requests, merged.
async function fetchScoreboard(sport, anchor, span) {
  const days = windowDays(sport, anchor, span);
  const results = await Promise.allSettled(days.map((d) => fetchDay(sport, d)));
  const ok = results.filter((r) => r.status === "fulfilled");
  if (!ok.length) throw results[0].reason || new Error("ESPN request failed");
  const seen = new Set();
  return ok.flatMap((r) => r.value)
    .filter((g) => (seen.has(g.id) ? false : (seen.add(g.id), true)))
    .sort((a, b) => new Date(a.date) - new Date(b.date));
}

async function fetchTeamDirectory(sport) {
  const res = await fetch(`${ESPN}${SPORTS[sport].path}/teams`);
  if (!res.ok) throw new Error("teams");
  const j = await res.json();
  const list = (j.sports && j.sports[0].leagues[0].teams) || [];
  return list.map(({ team: t }) => ({
    sport, id: t.id, abbr: t.abbreviation, name: t.displayName,
    logo: (t.logos && t.logos[0] && t.logos[0].href) || fallbackLogo(sport, t.abbreviation),
  }));
}

// Compact, Claude-friendly version of a game. This is the ONLY data Claude sees.
const compactGame = (g, d) => ({
  sport: SPORTS[g.sport].label,
  week: g.sport === "nfl" && g.week ? g.week : undefined,
  status: g.state === "post" ? "Final" : g.state === "in" ? "In progress" : "Scheduled",
  detail: g.detail,
  away: { team: g.teams[0] && g.teams[0].name, score: g.teams[0] && g.teams[0].score, record: g.teams[0] && g.teams[0].record },
  home: { team: g.teams[1] && g.teams[1].name, score: g.teams[1] && g.teams[1].score, record: g.teams[1] && g.teams[1].record },
  topPerformers: d && d.topPerformers && d.topPerformers.length
    ? d.topPerformers
    : g.teams.flatMap((t) => t.leaders.map((l) => ({ team: t.name, category: l.category, player: l.player, stat: l.stat }))),
  storyline: (d && d.story) || undefined,
  scoringPlays: d && d.scoringPlays && d.scoringPlays.length ? d.scoringPlays : undefined,
  note: g.note || undefined,
  venue: g.venue || undefined,
});

// Works out comeback / lead-change facts from ESPN's own scoring plays and period scores.
function deriveStory(s) {
  try {
    const comp = s.header && s.header.competitions && s.header.competitions[0];
    if (!comp) return null;
    const winner = (comp.competitors || []).find((c) => c.winner);
    const story = {};
    const plays = s.scoringPlays || [];
    if (winner && plays.length) {
      const wHome = winner.homeAway === "home";
      let worst = 0, changes = 0, prev = 0;
      plays.forEach((p) => {
        const d = wHome ? p.homeScore - p.awayScore : p.awayScore - p.homeScore;
        if (isNaN(d)) return;
        if (d < worst) worst = d;
        const sign = Math.sign(d);
        if (sign !== 0) { if (prev !== 0 && sign !== prev) changes++; prev = sign; }
      });
      story.winner = winner.team && winner.team.displayName;
      story.leadChanges = changes;
      story.winnerLargestDeficitOvercome = worst < 0 ? -worst : 0;
    }
    const lines = (comp.competitors || []).map((c) => ({ team: c.team && c.team.displayName, pointsByPeriod: (c.linescores || []).map((l) => l.displayValue) }));
    if (lines.length && lines.every((l) => l.pointsByPeriod.length)) story.periodScores = lines;
    return Object.keys(story).length ? story : null;
  } catch { return null; }
}
const scoringPlaysOf = (s, n = 16) => (s.scoringPlays || []).slice(0, n).map((p) => ({
  period: p.period && p.period.number,
  clock: p.clock && p.clock.displayValue,
  team: p.team && (p.team.abbreviation || p.team.displayName),
  play: p.text ? String(p.text).slice(0, 170) : undefined,
  awayScore: p.awayScore,
  homeScore: p.homeScore,
}));

// One extra ESPN request per game: top stats, key plays, and comeback facts.
async function fetchGameDetails(g) {
  try {
    const r = await fetch(`${ESPN}${SPORTS[g.sport].path}/summary?event=${g.eventId}`);
    if (!r.ok) return null;
    const s = await r.json();
    const topPerformers = (s.leaders || []).flatMap((t) => (t.leaders || []).slice(0, 3).map((l) => ({
      team: t.team && t.team.displayName,
      category: l.displayName,
      player: l.leaders && l.leaders[0] && l.leaders[0].athlete && l.leaders[0].athlete.displayName,
      stat: l.leaders && l.leaders[0] && l.leaders[0].displayValue,
    }))).filter((x) => x.player);
    return { topPerformers, story: deriveStory(s), scoringPlays: scoringPlaysOf(s) };
  } catch { return null; }
}
async function fetchDetailsFor(games) {
  const live = games.filter((g) => g.state !== "pre");
  const res = await Promise.all(live.map((g) => fetchGameDetails(g)));
  return Object.fromEntries(live.map((g, i) => [g.id, res[i]]));
}

async function fetchTeamData(team) {
  const base = `${ESPN}${SPORTS[team.sport].path}`;
  // 1. Find the team's latest finished game by scanning recent scoreboards, a week at a time.
  const today = new Date();
  let last = null;
  for (let chunk = 0; chunk < 5 && !last; chunk++) {
    const days = Array.from({ length: 7 }, (_, i) => addDays(today, -(chunk * 7 + i)));
    const res = await Promise.allSettled(days.map((d) => fetchDay(team.sport, d)));
    if (chunk === 0 && res.every((r) => r.status === "rejected")) {
      throw new Error("Couldn't reach the ESPN scoreboard. Check your connection and try again.");
    }
    const mine = res.filter((r) => r.status === "fulfilled").flatMap((r) => r.value)
      .filter((g) => g.state === "post" && g.teams.some((t) => t.abbr === team.abbr))
      .sort((a, b) => new Date(b.date) - new Date(a.date));
    if (mine.length) last = mine[0];
  }
  if (!last) throw new Error(`No finished ${team.name} game found in the last 5 weeks. The season may not have started yet.`);

  // 2. Game details (optional extras)
  let leaders = [], scoringPlays = [], story = null;
  try {
    const s = await (await fetch(`${base}/summary?event=${last.eventId}`)).json();
    story = deriveStory(s);
    leaders = (s.leaders || []).map((t) => ({
      team: t.team && t.team.displayName,
      categories: (t.leaders || []).slice(0, 4).map((l) => ({
        category: l.displayName,
        player: l.leaders && l.leaders[0] && l.leaders[0].athlete && l.leaders[0].athlete.displayName,
        stat: l.leaders && l.leaders[0] && l.leaders[0].displayValue,
      })),
    }));
    scoringPlays = (s.scoringPlays || []).slice(0, 20).map((p) => ({
      period: p.period && p.period.number, clock: p.clock && p.clock.displayValue,
      team: p.team && p.team.displayName, text: p.text, awayScore: p.awayScore, homeScore: p.homeScore,
    }));
  } catch { /* optional */ }

  // 3. Record and next game (optional extras)
  let next = "No upcoming game found", record = null, standing = null;
  try {
    for (const ref of [team.id, team.abbr && team.abbr.toLowerCase()].filter(Boolean)) {
      const r = await fetch(`${base}/teams/${ref}/schedule`);
      if (!r.ok) continue;
      const j = await r.json();
      record = j.team && j.team.recordSummary;
      standing = j.team && j.team.standingSummary;
      const up = (j.events || []).map((e) => ({ e, c: e.competitions && e.competitions[0] }))
        .filter((x) => x.c && x.c.status && x.c.status.type && x.c.status.type.state === "pre")
        .sort((a, b) => new Date(a.e.date) - new Date(b.e.date))[0];
      if (up) next = { date: up.e.date, name: up.e.name, status: up.c.status.type.shortDetail };
      break;
    }
  } catch { /* optional */ }

  const me = last.teams.find((t) => t.abbr === team.abbr);
  return {
    team: team.name,
    record: record || (me && me.record) || undefined,
    standing: standing || undefined,
    lastGame: compactGame(last),
    keyPerformers: leaders,
    storyline: story || undefined,
    scoringPlays,
    nextGame: next,
  };
}

/* ==========================================================================
   LAYER 2 — Claude script generation
   ========================================================================== */
async function callClaude(prompt, apiKey, mode) {
  const r = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": apiKey,
      "anthropic-version": "2023-06-01",
      "anthropic-dangerous-direct-browser-access": "true",
    },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 2000,
      messages: [{ role: "user", content: prompt + guardFor(mode) }],
    }),
  });
  if (r.status === 401) throw new Error("Your Anthropic API key was rejected. Check it in Settings.");
  if (!r.ok) throw new Error(`Script generation failed (${r.status}).`);
  const d = await r.json();
  const text = (d.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
  if (!text) throw new Error("Claude returned an empty script.");
  return text;
}

/* ==========================================================================
   LAYER 3 — ElevenLabs text-to-speech
   ========================================================================== */
async function synthesize(text, key, voiceId) {
  const r = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}?output_format=mp3_44100_64`, {
    method: "POST",
    headers: { "xi-api-key": key, "Content-Type": "application/json", Accept: "audio/mpeg" },
    body: JSON.stringify({
      text,
      model_id: "eleven_turbo_v2_5", // half the credit cost of multilingual_v2; keeps the free tier usable
      voice_settings: { stability: 0.4, similarity_boost: 0.8, style: 0.35, use_speaker_boost: true },
    }),
  });
  if (!r.ok) {
    let detail = "";
    try { const j = await r.json(); detail = (j.detail && (j.detail.message || j.detail)) || ""; } catch { /* ignore */ }
    throw new Error(`ElevenLabs returned ${r.status}${typeof detail === "string" && detail ? `: ${detail}` : ""}`);
  }
  return await r.blob();
}

async function computePeaks(blob, n = 84) {
  try {
    const buf = await blob.arrayBuffer();
    const Ctx = window.AudioContext || window.webkitAudioContext;
    const ctx = new Ctx();
    const audio = await ctx.decodeAudioData(buf);
    if (ctx.close) ctx.close();
    const ch = audio.getChannelData(0);
    const size = Math.max(1, Math.floor(ch.length / n));
    const out = [];
    for (let i = 0; i < n; i++) {
      let s = 0, c = 0;
      for (let j = 0; j < size; j += 24) { s += Math.abs(ch[i * size + j] || 0); c++; }
      out.push(s / (c || 1));
    }
    const m = Math.max(...out) || 1;
    return out.map((v) => Math.max(0.08, v / m));
  } catch { return null; }
}
const pseudoPeaks = (seed, n = 84) => {
  let x = 0; for (const ch of String(seed)) x = (x * 31 + ch.charCodeAt(0)) >>> 0;
  return Array.from({ length: n }, (_, i) => { x = (x * 1664525 + 1013904223) >>> 0; return 0.18 + 0.7 * Math.abs(Math.sin(i / 5)) * ((x % 100) / 100 * 0.6 + 0.4); });
};

/* ==========================================================================
   Small components
   ========================================================================== */
function TeamLogo({ src, abbr, size = 36 }) {
  const [bad, setBad] = useState(false);
  useEffect(() => setBad(false), [src]);
  if (!src || bad) {
    return <span className="rp-logo-fallback" style={{ width: size, height: size, fontSize: size * 0.34 }}>{abbr}</span>;
  }
  return <img src={src} alt="" width={size} height={size} style={{ width: size, height: size, objectFit: "contain" }} onError={() => setBad(true)} />;
}

function StatusChip({ game }) {
  if (game.state === "in") return <span className="rp-chip rp-chip-live"><i />Live · {game.detail}</span>;
  if (game.state === "post") return <span className="rp-chip rp-chip-final">{game.detail && game.detail.startsWith("Final") ? game.detail : "Final"}</span>;
  return <span className="rp-chip rp-chip-sched">{game.detail}</span>;
}

function GameCard({ game, selected, onToggle, favKeys }) {
  const started = game.state !== "pre";
  const top = game.teams.length ? game.teams.map((t) => parseFloat(t.score)).filter((n) => !isNaN(n)) : [];
  const max = top.length ? Math.max(...top) : null;
  return (
    <div className={`rp-game ${selected ? "is-on" : ""}`}>
      <div className="rp-game-top">
        <StatusChip game={game} />
        <button className={`rp-check ${selected ? "is-on" : ""}`} onClick={onToggle} aria-pressed={selected}
          aria-label={selected ? "Remove game from episode" : "Add game to episode"}>
          {selected && <Check size={14} strokeWidth={3} />}
        </button>
      </div>
      {game.teams.map((t) => {
        const fav = favKeys.has(teamKey(game.sport, t.abbr));
        const lead = started && max !== null && parseFloat(t.score) === max;
        return (
          <div className="rp-row" key={t.id}>
            <TeamLogo src={t.logo || fallbackLogo(game.sport, t.abbr)} abbr={t.abbr} size={38} />
            <div className="rp-row-name">
              <span className={`rp-h rp-row-title ${started && !lead ? "is-dim" : ""}`}>
                {t.name}{fav && <Star size={13} fill={"#E8283C"} stroke="#E8283C" style={{ marginLeft: 6 }} aria-label="Favorite" />}
              </span>
              {t.record && <span className="rp-small">{t.record}</span>}
            </div>
            <span className={`rp-h rp-score ${started && !lead ? "is-dim" : ""}`}>{started ? t.score : ""}</span>
          </div>
        );
      })}
      {(game.note || game.venue) && <p className="rp-small rp-game-note">{game.note || game.venue}</p>}
    </div>
  );
}

function GameTile({ game, selected, onToggle, favKeys }) {
  const started = game.state !== "pre";
  const nums = game.teams.map((t) => parseFloat(t.score)).filter((n) => !isNaN(n));
  const max = nums.length ? Math.max(...nums) : null;
  const status = game.state === "post" ? (game.detail && game.detail.startsWith("Final") ? game.detail : "Final")
    : game.state === "in" ? `Live ${game.detail}` : game.detail;
  return (
    <button role="checkbox" aria-checked={selected} className={`rp-tile ${selected ? "is-on" : ""}`} onClick={onToggle}>
      <span className="rp-tile-top">
        <span className={game.state === "in" ? "is-live" : ""}>{SPORTS[game.sport].label} {status}</span>
        {selected && <span className="rp-tile-check"><Check size={12} strokeWidth={3} /></span>}
      </span>
      <span className="rp-tile-match">
        {game.teams.map((t, i) => {
          const lead = started && max !== null && parseFloat(t.score) === max;
          const fav = favKeys.has(teamKey(game.sport, t.abbr));
          return (
            <React.Fragment key={t.id}>
              {i === 1 && <span className="rp-tile-sep">{started ? "–" : "at"}</span>}
              <span className={`rp-tile-team ${started && !lead ? "is-dim" : ""}`}>
                <TeamLogo src={t.logo || fallbackLogo(game.sport, t.abbr)} abbr={t.abbr} size={30} />
                <b className="rp-h rp-tile-abbr">{t.abbr}{fav && <Star size={11} fill="#E8283C" stroke="#E8283C" aria-label="Favorite" />}</b>
                {started && <b className="rp-h rp-tile-score">{t.score}</b>}
              </span>
            </React.Fragment>
          );
        })}
      </span>
    </button>
  );
}

function Waveform({ peaks, progress, onSeek }) {
  const ref = useRef(null);
  const seek = (e) => {
    const r = ref.current.getBoundingClientRect();
    onSeek(Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)));
  };
  return (
    <div className="rp-wave" ref={ref} onClick={seek} role="slider" aria-label="Seek" aria-valuemin={0} aria-valuemax={100}
      aria-valuenow={Math.round(progress * 100)} tabIndex={0}
      onKeyDown={(e) => { if (e.key === "ArrowRight") onSeek(Math.min(1, progress + 0.03)); if (e.key === "ArrowLeft") onSeek(Math.max(0, progress - 0.03)); }}>
      {peaks.map((p, i) => (
        <span key={i} style={{ height: `${p * 100}%`, background: i / peaks.length < progress ? "#E8283C" : "#CBD2DD" }} />
      ))}
    </div>
  );
}

function Modal({ title, onClose, children, wide }) {
  useEffect(() => {
    const h = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [onClose]);
  return (
    <div className="rp-scrim" onMouseDown={onClose}>
      <div className="rp-modal" style={wide ? { width: 520 } : null} onMouseDown={(e) => e.stopPropagation()} role="dialog" aria-label={title}>
        <div className="rp-modal-head">
          <h2 className="rp-h" style={{ fontSize: 26, margin: 0 }}>{title}</h2>
          <button className="rp-icon" onClick={onClose} aria-label="Close"><X size={18} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

/* ==========================================================================
   App
   ========================================================================== */
export default function App() {
  const [booted, setBooted] = useState(false);
  const [favorites, setFavorites] = useState(DEFAULT_TEAMS);
  const [episodes, setEpisodes] = useState([]);
  const [settings, setSettings] = useState({ key: "", claudeKey: "", voiceId: VOICES[0].id });
  const [teamDir, setTeamDir] = useState({});

  const [tab, setTab] = useState("all");
  const [mode, setMode] = useState("league");
  const [focusKey, setFocusKey] = useState(null);
  const [anchor, setAnchor] = useState(() => new Date());

  const [games, setGames] = useState([]);
  const [loadingGames, setLoadingGames] = useState(false);
  const [boardError, setBoardError] = useState(null);
  const [overrides, setOverrides] = useState({});
  const [jumping, setJumping] = useState(false);
  const [view, setView] = useState("compact");

  const [stage, setStage] = useState(0); // 0 idle, 1 fetch, 2 script, 3 audio
  const [notice, setNotice] = useState(null);

  const [playback, setPlayback] = useState(null); // {ep, blob, url, peaks}
  const [playing, setPlaying] = useState(false);
  const [time, setTime] = useState(0);
  const [dur, setDur] = useState(0);
  const [rate, setRate] = useState(1);
  const [showScript, setShowScript] = useState(false);
  const [speaking, setSpeaking] = useState(false);

  const [showSettings, setShowSettings] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [draft, setDraft] = useState(settings);

  const audioRef = useRef(null);
  const loadId = useRef(0);

  /* ----- boot: restore favorites, episodes, settings ----- */
  useEffect(() => {
    (async () => {
      const t = await store.get("replay:teams");
      if (t && t.length) setFavorites(t);
      const e = await store.get("replay:episodes");
      if (e) setEpisodes(e);
      const s = await store.get("replay:settings");
      if (s) { const m = { key: "", claudeKey: "", voiceId: VOICES[0].id, ...s }; setSettings(m); setDraft(m); }
      setBooted(true);
    })();
    SPORT_KEYS.forEach((sp) => {
      fetchTeamDirectory(sp).then((list) => setTeamDir((d) => ({ ...d, [sp]: list }))).catch(() => {});
    });
  }, []);
  useEffect(() => { if (booted) store.set("replay:teams", favorites); }, [favorites, booted]);

  /* ----- favorites enriched with live ESPN logos/ids ----- */
  const favTeams = useMemo(() => favorites.map((f) => {
    const hit = (teamDir[f.sport] || []).find((t) => t.abbr === f.abbr);
    return { ...f, key: teamKey(f.sport, f.abbr), id: (hit && hit.id) || f.id || DEFAULT_IDS[teamKey(f.sport, f.abbr)], logo: (hit && hit.logo) || fallbackLogo(f.sport, f.abbr) };
  }), [favorites, teamDir]);
  const favKeys = useMemo(() => new Set(favTeams.map((t) => t.key)), [favTeams]);
  const focus = favTeams.find((t) => t.key === focusKey) || favTeams[0];

  /* ----- scoreboard loading ----- */
  useEffect(() => {
    const id = ++loadId.current;
    setLoadingGames(true); setBoardError(null); setOverrides({});
    const sports = SPORTS[tab] ? [tab] : SPORT_KEYS;
    Promise.allSettled(sports.map((sp) => fetchScoreboard(sp, anchor, spanFor(sp, tab)))).then((results) => {
      if (id !== loadId.current) return;
      const ok = results.filter((r) => r.status === "fulfilled").flatMap((r) => r.value);
      const failed = results.filter((r) => r.status === "rejected");
      setGames(ok);
      if (failed.length === results.length) {
        setBoardError(`Couldn't reach the ESPN scoreboard (${(failed[0].reason && failed[0].reason.message) || "request failed"}). Check your connection and try again.`);
      } else if (failed.length) {
        setBoardError("Some sports didn't load, so this board may be incomplete.");
      }
      setLoadingGames(false);
    });
  }, [tab, anchor]);

  const visible = useMemo(() => {
    if (tab === "mine") return games.filter((g) => g.teams.some((t) => favKeys.has(teamKey(g.sport, t.abbr))));
    return games;
  }, [games, tab, favKeys]);
  const isSel = (g) => (g.id in overrides ? overrides[g.id] : g.state !== "pre");
  const selectedGames = visible.filter(isSel);
  const grouped = useMemo(() => {
    const m = {};
    visible.forEach((g) => { (m[g.sport] = m[g.sport] || []).push(g); });
    return SPORT_KEYS.filter((k) => m[k]).map((k) => [k, m[k]]);
  }, [visible]);

  async function jumpToLatest() {
    setJumping(true);
    try {
      const sports = SPORTS[tab] ? [tab] : SPORT_KEYS;
      const today = new Date(); let best = null;
      for (let chunk = 0; chunk < 8 && !best; chunk++) {
        const days = Array.from({ length: 7 }, (_, i) => addDays(today, -(chunk * 7 + i)));
        const res = await Promise.allSettled(sports.flatMap((sp) => days.map((d) => fetchDay(sp, d))));
        if (chunk === 0 && res.every((r) => r.status === "rejected")) throw new Error("network");
        res.filter((r) => r.status === "fulfilled").flatMap((r) => r.value).filter((g) => g.state === "post")
          .forEach((g) => { const d = new Date(g.date); if (!best || d > best) best = d; });
      }
      if (best) setAnchor(best);
      else setNotice({ kind: "warn", text: "No finished games in the last 8 weeks. This league may be in its off-season." });
    } catch { setNotice({ kind: "warn", text: "Couldn't search for recent games. Check your connection." }); }
    setJumping(false);
  }

  /* ----- mode / tab / team interactions ----- */
  const chooseMode = (m) => {
    setMode(m);
    if (m === "myteams") setTab("mine");
    if (m === "league" && !SPORTS[tab]) setTab("nfl");
    if (m === "single" && focus) setTab(focus.sport);
  };
  const chooseTeam = (t) => { setFocusKey(t.key); setMode("single"); setTab(t.sport); };
  const removeTeam = (t) => setFavorites((f) => f.filter((x) => teamKey(x.sport, x.abbr) !== t.key));
  const addTeam = (t) => { setFavorites((f) => [...f, { sport: t.sport, abbr: t.abbr, name: t.name, id: t.id }]); setShowAdd(false); };

  const gate = (() => {
    if (mode === "league") return SPORTS[tab] ? (selectedGames.length ? null : "Select at least one game below.") : "Open a sport tab (NFL, NBA, MLB or NHL) to recap that league.";
    if (mode === "myteams") return !favTeams.length ? "Add a favorite team first." : tab !== "mine" ? "Open the My Teams tab to pick games." : selectedGames.length ? null : "None of your teams played in this window.";
    return focus ? null : "Add a favorite team first.";
  })();
  const barText = mode === "league"
    ? `${selectedGames.length} ${selectedGames.length === 1 ? "game" : "games"} in this ${SPORTS[tab] ? SPORTS[tab].label : "league"} recap`
    : mode === "myteams" ? `${selectedGames.length} ${selectedGames.length === 1 ? "game" : "games"} for your teams`
    : focus ? `Latest game for the ${focus.name}` : "No team selected";

  /* ----- the pipeline: ESPN → Claude → ElevenLabs ----- */
  async function generate() {
    setNotice(null); setStage(1);
    try {
      if (!settings.claudeKey) throw new Error("Add your Anthropic API key in Settings first.");
      // 1. Fetch
      let prompt, title, subtitle, logos;
      const dateLabel = fmtShort(anchor);
      if (mode === "league") {
        const details = await fetchDetailsFor(selectedGames);
        const data = { sport: SPORTS[tab].label, window: windowLabel(tab, anchor), week: weekNum || undefined, games: selectedGames.map((g) => compactGame(g, details[g.id])) };
        prompt = PROMPTS.league.replace("{game_data}", JSON.stringify(data));
        title = tab === "nfl" && weekNum ? `NFL Week ${weekNum} recap` : `${SPORTS[tab].label} recap, ${dateLabel}`;
        subtitle = `${selectedGames.length} games`;
        logos = selectedGames.slice(0, 3).flatMap((g) => g.teams.slice(0, 1).map((t) => t.logo));
      } else if (mode === "myteams") {
        const details = await fetchDetailsFor(selectedGames);
        const data = { window: windowLabel("mine", anchor), games: selectedGames.map((g) => compactGame(g, details[g.id])) };
        prompt = PROMPTS.myteams.replace("{team_list}", favTeams.map((t) => t.name).join(", ")).replace("{game_data}", JSON.stringify(data));
        title = `My Teams, ${dateLabel}`;
        subtitle = `${selectedGames.length} games`;
        logos = favTeams.slice(0, 4).map((t) => t.logo);
      } else {
        const data = await fetchTeamData(focus);
        prompt = PROMPTS.single.replace("{team_name}", focus.name).replace("{game_data}", JSON.stringify(data));
        title = `${focus.name} review`;
        subtitle = data.lastGame.detail || data.lastGame.status;
        logos = [focus.logo];
      }

      // 2. Script
      setStage(2);
      const script = await callClaude(prompt, settings.claudeKey, mode);
      const words = script.split(/\s+/).length;

      // 3. Audio
      setStage(3);
      let blob = null, audioWarn = null;
      if (settings.key) {
        try { blob = await synthesize(script, settings.key, settings.voiceId); }
        catch (e) { audioWarn = `${e.message}. The script was saved, so you can retry audio from Settings.`; }
      } else {
        audioWarn = "Script ready. Add your ElevenLabs key in Settings to turn it into audio.";
      }

      // Save + play
      const id = Date.now().toString(36);
      let duration = Math.round(words / 2.5);
      let hasAudio = false;
      if (blob) {
        duration = await new Promise((res) => {
          const a = new Audio(URL.createObjectURL(blob));
          a.onloadedmetadata = () => res(a.duration || duration);
          a.onerror = () => res(duration);
        });
        hasAudio = await audioDB.put(id, blob);
      }
      const ep = { id, title, subtitle, mode, createdAt: Date.now(), duration: Math.round(duration), script, hasAudio, logos: logos.filter(Boolean) };
      const next = [ep, ...episodes];
      const dropped = next.slice(10);
      dropped.forEach((d) => audioDB.del(d.id));
      const kept = next.slice(0, 10);
      setEpisodes(kept);
      store.set("replay:episodes", kept);
      await startPlayback(ep, blob);
      if (audioWarn) setNotice({ kind: "warn", text: audioWarn });
      else if (blob && !hasAudio) setNotice({ kind: "warn", text: "Couldn't save this episode's audio in your browser, so it will only play now." });
    } catch (e) {
      const blocked = /Failed to fetch|NetworkError|Load failed/i.test(e.message);
      setNotice({ kind: "error", text: blocked ? "A network request was blocked. Check your connection and any ad or privacy blocker, then try again." : e.message });
    }
    setStage(0);
  }

  /* ----- playback ----- */
  async function startPlayback(ep, blob) {
    window.speechSynthesis && window.speechSynthesis.cancel(); setSpeaking(false);
    if (playback && playback.url) URL.revokeObjectURL(playback.url);
    setTime(0); setShowScript(false);
    if (!blob) { setPlayback({ ep, blob: null, url: null, peaks: null }); setPlaying(false); return; }
    const url = URL.createObjectURL(blob);
    setPlayback({ ep, blob, url, peaks: null });
    computePeaks(blob).then((peaks) => setPlayback((p) => (p && p.ep.id === ep.id ? { ...p, peaks: peaks || pseudoPeaks(ep.id) } : p)));
  }
  async function openEpisode(ep) {
    if (ep.hasAudio) {
      const saved = await audioDB.get(ep.id);
      if (saved) return startPlayback(ep, saved);
    }
    startPlayback(ep, null);
  }
  async function deleteEpisode(ep) {
    audioDB.del(ep.id);
    const next = episodes.filter((e) => e.id !== ep.id);
    setEpisodes(next); store.set("replay:episodes", next);
    if (playback && playback.ep.id === ep.id) { if (audioRef.current) audioRef.current.pause(); setPlayback(null); }
  }
  useEffect(() => {
    const a = audioRef.current; if (!a) return;
    if (playback && playback.url) {
      a.src = playback.url; a.playbackRate = rate;
      a.play().catch(() => {});
    } else { a.removeAttribute("src"); a.load(); setPlaying(false); setDur(0); }
    // eslint-disable-next-line
  }, [playback && playback.url]);
  const toggle = () => { const a = audioRef.current; if (!a || !a.src) return; a.paused ? a.play() : a.pause(); };
  const skip = (s) => { const a = audioRef.current; if (a) a.currentTime = Math.max(0, Math.min(a.duration || 0, a.currentTime + s)); };
  const seekTo = (r) => { const a = audioRef.current; if (a && a.duration) a.currentTime = r * a.duration; };
  const cycleRate = () => {
    const nx = rate === 1 ? 1.25 : rate === 1.25 ? 1.5 : 1;
    setRate(nx); if (audioRef.current) audioRef.current.playbackRate = nx;
  };
  const browserVoice = () => {
    const s = window.speechSynthesis; if (!s || !playback) return;
    if (speaking) { s.cancel(); setSpeaking(false); return; }
    const u = new SpeechSynthesisUtterance(playback.ep.script);
    u.onend = () => setSpeaking(false);
    s.speak(u); setSpeaking(true);
  };

  /* ----- settings ----- */
  const saveSettings = () => { setSettings(draft); store.set("replay:settings", draft); setShowSettings(false); };

  /* ----- add-team modal data ----- */
  const [q, setQ] = useState(""); const [qSport, setQSport] = useState("all");
  const addable = useMemo(() => SPORT_KEYS.flatMap((sp) => teamDir[sp] || [])
    .filter((t) => !favKeys.has(teamKey(t.sport, t.abbr)))
    .filter((t) => qSport === "all" || t.sport === qSport)
    .filter((t) => t.name.toLowerCase().includes(q.toLowerCase())), [teamDir, favKeys, q, qSport]);

  const peaks = playback && (playback.peaks || (playback.url ? pseudoPeaks(playback.ep.id) : null));
  const progress = dur ? time / dur : 0;
  const stepLabels = ["Fetching scores…", "Generating script…", "Creating audio…"];
  const tabs = [["all", "All"], ["nfl", "NFL"], ["nba", "NBA"], ["mlb", "MLB"], ["nhl", "NHL"], ["mine", "★ My Teams"]];
  const heading = tab === "all" ? "All sports" : tab === "mine" ? "My teams" : `${SPORTS[tab].label} scoreboard`;
  const span = tab === "mine" || tab === "nfl" ? 7 : 1;
  const weekNum = tab === "nfl" ? (games.find((g) => g.week) || {}).week : null;
  const heroTitle = weekNum ? `NFL Week ${weekNum}` : heading;
  const dateLine = windowLabel(tab, anchor);
  const heroSub = `${dateLine}${tab === "all" ? " (NFL shows the 7 days ending on this date)" : ""}. ${loadingGames ? "Loading games…" : `${visible.length} ${visible.length === 1 ? "game" : "games"}. Select games to include.`}`;
  const badgeSports = SPORTS[tab] ? [tab] : SPORT_KEYS.filter((k) => visible.some((g) => g.sport === k));
  const renderGames = (list) => view === "compact" ? (
    <div className="rp-tiles">
      {list.map((g) => <GameTile key={g.id} game={g} favKeys={favKeys} selected={isSel(g)} onToggle={() => setOverrides((o) => ({ ...o, [g.id]: !isSel(g) }))} />)}
    </div>
  ) : (
    <div className="rp-grid">
      {list.map((g) => <GameCard key={g.id} game={g} favKeys={favKeys} selected={isSel(g)} onToggle={() => setOverrides((o) => ({ ...o, [g.id]: !isSel(g) }))} />)}
    </div>
  );

  return (
    <div className="rp">
      <style>{CSS}</style>
      <audio ref={audioRef}
        onPlay={() => setPlaying(true)} onPause={() => setPlaying(false)} onEnded={() => setPlaying(false)}
        onTimeUpdate={(e) => setTime(e.target.currentTime)} onLoadedMetadata={(e) => setDur(e.target.duration)} />

      {/* ===== Header ===== */}
      <header className="rp-head">
        <div className="rp-brand">
          <img src={LOGO} alt="Replay" className="rp-logo" />
          <span className="rp-tagline">Your Instant Replay, Every Monday Morning</span>
        </div>
        <nav className="rp-tabs" aria-label="Sport">
          {tabs.map(([k, label]) => (
            <button key={k} className={`rp-h rp-tab ${tab === k ? "is-on" : ""}`} onClick={() => setTab(k)} aria-current={tab === k}>{label}</button>
          ))}
        </nav>
        <button className="rp-voice-pill" onClick={() => { setDraft(settings); setShowSettings(true); }}>
          <span className={`rp-dot ${settings.claudeKey ? "is-ok" : ""}`} />
          {settings.claudeKey && settings.key ? "Voice ready" : settings.claudeKey ? "Script only" : "Add API keys"}
          <Settings size={16} />
        </button>
      </header>

      <main className="rp-shell">
        {/* ===== Sidebar ===== */}
        <aside className="rp-side">
          <section className="rp-card">
            <h2 className="rp-h rp-card-title">Podcast mode</h2>
            <div role="radiogroup" className="rp-modes">
              {MODES.map((m) => {
                const Icon = m.icon;
                return (
                  <button key={m.id} role="radio" aria-checked={mode === m.id} className={`rp-mode ${mode === m.id ? "is-on" : ""}`} onClick={() => chooseMode(m.id)}>
                    <span className="rp-mode-icon"><Icon size={18} /></span>
                    <span><b className="rp-h">{m.title}</b><span className="rp-small">{m.blurb}</span></span>
                  </button>
                );
              })}
            </div>
          </section>

          <section className="rp-card">
            <div className="rp-card-head">
              <h2 className="rp-h rp-card-title">My teams</h2>
              <button className="rp-add" onClick={() => { setQ(""); setQSport("all"); setShowAdd(true); }}><Plus size={15} />Add team</button>
            </div>
            {favTeams.length === 0 && <p className="rp-small">No favorites yet. Add a team to build your own podcast.</p>}
            <ul className="rp-teams">
              {favTeams.map((t) => (
                <li key={t.key} className={`rp-team ${mode === "single" && focus && focus.key === t.key ? "is-on" : ""}`}>
                  <button className="rp-team-main" onClick={() => chooseTeam(t)} title="Review this team">
                    <TeamLogo src={t.logo} abbr={t.abbr} size={34} />
                    <span><b className="rp-h">{t.name}</b><span className="rp-small">{SPORTS[t.sport].label}</span></span>
                  </button>
                  <button className="rp-icon" onClick={() => removeTeam(t)} aria-label={`Remove ${t.name}`}><X size={15} /></button>
                </li>
              ))}
            </ul>
          </section>
        </aside>

        {/* ===== Scoreboard ===== */}
        <section className="rp-main">
          {mode === "single" && focus && (
            <div className="rp-callout">
              <TeamLogo src={focus.logo} abbr={focus.abbr} size={34} />
              <p>Reviewing the <b>{focus.name}</b>. Replay finds their most recent finished game on its own, whatever date is shown here.</p>
            </div>
          )}

          <div className="rp-hero">
            <div className="rp-hero-top">
              <div>
                <h1 className="rp-h rp-title">{heroTitle}</h1>
                <p className="rp-small rp-hero-sub">{heroSub}</p>
              </div>
              <div className="rp-badges">
                {badgeSports.map((k) => <span key={k} className="rp-badge" style={{ background: SPORT_COLORS[k] }}>{SPORTS[k].label}</span>)}
              </div>
            </div>

            <div className="rp-toolbar">
              <div className="rp-dates">
                <button className="rp-icon rp-boxed" onClick={() => setAnchor((d) => addDays(d, -stepFor(tab)))} aria-label="Earlier"><ChevronLeft size={18} /></button>
                <input type="date" className="rp-date" value={toInput(anchor)} onChange={(e) => e.target.value && setAnchor(fromInput(e.target.value))} aria-label="Pick a date" />
                <button className="rp-icon rp-boxed" onClick={() => setAnchor((d) => addDays(d, stepFor(tab)))} aria-label="Later"><ChevronRight size={18} /></button>
                <button className="rp-ghost" onClick={() => setAnchor(new Date())}>Today</button>
              </div>
              <div className="rp-seg" role="group" aria-label="Scoreboard view">
                <button className={view === "compact" ? "is-on" : ""} aria-pressed={view === "compact"} onClick={() => setView("compact")}>Compact</button>
                <button className={view === "detailed" ? "is-on" : ""} aria-pressed={view === "detailed"} onClick={() => setView("detailed")}>Detailed</button>
              </div>
            </div>

            {visible.length > 0 && (
              <div className="rp-selbar">
                <span className="rp-small"><b>{selectedGames.length}</b> of {visible.length} selected for the episode</span>
                <span>
                  <button className="rp-link" onClick={() => setOverrides(Object.fromEntries(visible.map((g) => [g.id, true])))}>Select all</button>
                  <button className="rp-link" onClick={() => setOverrides(Object.fromEntries(visible.map((g) => [g.id, false])))}>Clear</button>
                </span>
              </div>
            )}

            {boardError && <div className="rp-note is-warn">{boardError}</div>}

            {loadingGames ? (
              <div className="rp-tiles">{[0, 1, 2, 3, 4, 5].map((i) => <div key={i} className="rp-tile rp-skel" />)}</div>
            ) : visible.length === 0 ? (
              <div className="rp-empty">
                <img src={LOGO} alt="" />
                <h3 className="rp-h">{tab === "mine" ? "None of your teams played in this window" : "No games on this date"}</h3>
                <p>This league may be between seasons, or nothing was scheduled. Jump to the most recent finished games, or pick another date.</p>
                <button className="rp-primary-sm" onClick={jumpToLatest} disabled={jumping}>{jumping ? "Searching…" : "Jump to the latest games"}</button>
              </div>
            ) : (
              grouped.map(([sp, list]) => (
                <div key={sp} className="rp-group">
                  {(tab === "all" || tab === "mine") && <h3 className="rp-h rp-group-title">{SPORTS[sp].label}</h3>}
                  {renderGames(list)}
                </div>
              ))
            )}
          </div>

          {/* ===== Generate bar ===== */}
          <div className="rp-bar">
            {notice && (
              <div className={`rp-note ${notice.kind === "error" ? "is-error" : "is-warn"}`} role="status">
                <span>{notice.text}</span>
                <button className="rp-icon" onClick={() => setNotice(null)} aria-label="Dismiss"><X size={14} /></button>
              </div>
            )}
            {stage > 0 && (
              <ol className="rp-steps">
                {stepLabels.map((l, i) => (
                  <li key={l} className={stage > i + 1 ? "is-done" : stage === i + 1 ? "is-now" : ""}>
                    <span className="rp-step-dot">{stage > i + 1 ? <Check size={12} strokeWidth={3} /> : stage === i + 1 ? <Loader2 size={12} className="rp-spin" /> : null}</span>{l}
                  </li>
                ))}
              </ol>
            )}
            <div className="rp-bar-row">
              <div>
                <b className="rp-h" style={{ fontSize: 20 }}>{barText}</b>
                <p className="rp-small">{gate || "Ready when you are. Takes about 30 seconds."}</p>
              </div>
              <div className="rp-bar-btns">
              {mode === "league" && <button className="rp-ghost rp-ghost-lg" disabled={stage > 0} onClick={() => chooseMode("myteams")}>My teams only</button>}
              <button className={`rp-primary ${stage > 0 ? "is-busy" : ""}`} disabled={!!gate || stage > 0} onClick={generate}>
                {stage > 0 ? <><Loader2 size={18} className="rp-spin" />{stepLabels[stage - 1]}</> : <><Mic size={18} />Generate episode</>}
              </button>
              </div>
            </div>
          </div>
        </section>

        {/* ===== Player ===== */}
        <aside className="rp-right">
          <section className="rp-card rp-player">
            <h2 className="rp-h rp-card-title">Now playing</h2>
            {!playback ? (
              <div className="rp-idle">
                <img src={LOGO} alt="" />
                <p>Pick a mode, choose your games and hit Generate. Your episode plays here.</p>
              </div>
            ) : (
              <>
                <div className="rp-np-head">
                  <div className="rp-np-logos">{playback.ep.logos.slice(0, 4).map((l, i) => <TeamLogo key={i} src={l} abbr="" size={30} />)}</div>
                  <h3 className="rp-h rp-np-title">{playback.ep.title}</h3>
                  <p className="rp-small">{playback.ep.subtitle}</p>
                </div>
                {playback.url ? (
                  <>
                    <Waveform peaks={peaks} progress={progress} onSeek={seekTo} />
                    <div className="rp-times"><span>{fmtTime(time)}</span><span>{fmtTime(dur)}</span></div>
                    <div className="rp-ctrls">
                      <button className="rp-icon rp-boxed" onClick={() => skip(-15)} aria-label="Back 15 seconds"><RotateCcw size={18} /></button>
                      <button className="rp-play" onClick={toggle} aria-label={playing ? "Pause" : "Play"}>{playing ? <Pause size={24} fill="#fff" /> : <Play size={24} fill="#fff" />}</button>
                      <button className="rp-icon rp-boxed" onClick={() => skip(15)} aria-label="Forward 15 seconds"><RotateCw size={18} /></button>
                      <button className="rp-ghost" onClick={cycleRate} aria-label="Playback speed">{rate}x</button>
                    </div>
                  </>
                ) : (
                  <div className="rp-noaudio">
                    <p className="rp-small">{playback.ep.hasAudio ? "Couldn't load the saved audio for this episode." : "This episode has a script but no audio yet."}</p>
                    <button className="rp-ghost" onClick={browserVoice}><Volume2 size={16} />{speaking ? "Stop" : "Read aloud with browser voice"}</button>
                  </div>
                )}
                <button className="rp-link" onClick={() => setShowScript((s) => !s)}><FileText size={14} />{showScript ? "Hide script" : "Read the script"}</button>
                {showScript && <div className="rp-script">{playback.ep.script}</div>}
              </>
            )}
          </section>

          <section className="rp-card">
            <h2 className="rp-h rp-card-title">Recent episodes</h2>
            {episodes.length === 0 ? <p className="rp-small">Episodes you generate are saved here so you can replay them.</p> : (
              <ul className="rp-eps">
                {episodes.map((ep) => (
                  <li key={ep.id} className={playback && playback.ep.id === ep.id ? "is-on" : ""}>
                    <button className="rp-ep-main" onClick={() => openEpisode(ep)}>
                      <span className="rp-ep-play"><Play size={14} fill="#fff" /></span>
                      <span>
                        <b className="rp-h">{ep.title}</b>
                        <span className="rp-small">{new Date(ep.createdAt).toLocaleDateString(undefined, { month: "short", day: "numeric" })}, {fmtTime(ep.duration)}{ep.hasAudio ? "" : ", script only"}</span>
                      </span>
                    </button>
                    <button className="rp-icon" onClick={() => deleteEpisode(ep)} aria-label={`Delete ${ep.title}`}><Trash2 size={15} /></button>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </aside>
      </main>

      {/* ===== Settings ===== */}
      {showSettings && (
        <Modal title="Settings" onClose={() => setShowSettings(false)}>
          <label className="rp-field">Anthropic API key (writes the script)
            <input type="password" value={draft.claudeKey} onChange={(e) => setDraft({ ...draft, claudeKey: e.target.value.trim() })} placeholder="sk-ant-..." autoComplete="off" />
            <span className="rp-small">Saved only in this browser and sent only to Anthropic.</span>
          </label>
          <label className="rp-field">ElevenLabs API key (turns the script into audio)
            <input type="password" value={draft.key} onChange={(e) => setDraft({ ...draft, key: e.target.value.trim() })} placeholder="Paste your key" autoComplete="off" />
            <span className="rp-small">Saved only in this browser and sent only to ElevenLabs. Optional: without it you still get a script.</span>
          </label>
          <label className="rp-field">Broadcaster voice
            <select value={VOICES.some((v) => v.id === draft.voiceId) ? draft.voiceId : "custom"} onChange={(e) => e.target.value !== "custom" && setDraft({ ...draft, voiceId: e.target.value })}>
              {VOICES.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}
              <option value="custom">Custom voice ID…</option>
            </select>
          </label>
          <label className="rp-field">Voice ID
            <input value={draft.voiceId} onChange={(e) => setDraft({ ...draft, voiceId: e.target.value.trim() })} />
          </label>
          <div className="rp-modal-foot">
            <button className="rp-ghost" onClick={() => setShowSettings(false)}>Cancel</button>
            <button className="rp-primary-sm" onClick={saveSettings}>Save settings</button>
          </div>
        </Modal>
      )}

      {/* ===== Add team ===== */}
      {showAdd && (
        <Modal title="Add a team" onClose={() => setShowAdd(false)} wide>
          <div className="rp-search"><Search size={16} /><input autoFocus placeholder="Search teams" value={q} onChange={(e) => setQ(e.target.value)} /></div>
          <div className="rp-pills">
            {["all", ...SPORT_KEYS].map((k) => <button key={k} className={`rp-pill ${qSport === k ? "is-on" : ""}`} onClick={() => setQSport(k)}>{k === "all" ? "All" : SPORTS[k].label}</button>)}
          </div>
          <ul className="rp-addlist">
            {addable.length === 0 && <li className="rp-small" style={{ padding: 12 }}>{Object.keys(teamDir).length ? "No teams match." : "Loading teams from ESPN…"}</li>}
            {addable.map((t) => (
              <li key={teamKey(t.sport, t.abbr)}>
                <button onClick={() => addTeam(t)}>
                  <TeamLogo src={t.logo} abbr={t.abbr} size={30} />
                  <b className="rp-h">{t.name}</b><span className="rp-small">{SPORTS[t.sport].label}</span>
                </button>
              </li>
            ))}
          </ul>
        </Modal>
      )}
    </div>
  );
}

/* ==========================================================================
   Styles
   ========================================================================== */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=Barlow:wght@400;500;600&display=swap');
.rp{--red:#E8283C;--red-d:#C81E31;--navy:#0A1628;--bg:#F0F2F5;--mute:#5B6678;--line:#E1E5EB;
  min-height:100vh;background:var(--bg);color:var(--navy);font-family:'Barlow','Helvetica Neue',Arial,sans-serif;font-size:15px;line-height:1.4}
.rp *{box-sizing:border-box}
.rp :where(button){font:inherit;color:inherit;cursor:pointer;border:0;background:none;padding:0}
.rp button:focus-visible,.rp input:focus-visible,.rp select:focus-visible,.rp [tabindex]:focus-visible{outline:3px solid #0A1628;outline-offset:2px}
.rp button:disabled{cursor:not-allowed}
.rp :where(h1,h2,h3,p,ul,ol){margin:0;padding:0}
.rp :where(ul,ol){list-style:none}
.rp-h{font-family:'Barlow Condensed','Arial Narrow','Helvetica Neue',sans-serif;font-weight:700;letter-spacing:.005em}
.rp-small{display:block;font-size:13px;color:var(--mute)}
.rp b{font-weight:700}

/* header */
.rp-head{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:28px;padding:8px 24px;background:#fff;border-bottom:1px solid var(--line)}
.rp-brand{display:flex;align-items:center;gap:14px;min-width:0}
.rp-logo{height:64px;width:auto;display:block}
.rp-tagline{font-size:13px;color:var(--mute);max-width:150px;line-height:1.25}
.rp-tabs{display:flex;gap:4px;flex:1;justify-content:center;flex-wrap:wrap}
.rp-tab{font-size:21px;padding:10px 14px;color:var(--mute);border-bottom:3px solid transparent;font-weight:700}
.rp-tab:hover{color:var(--navy)}
.rp-tab.is-on{color:var(--navy);border-bottom-color:var(--red)}
.rp-voice-pill{display:flex;align-items:center;gap:8px;padding:9px 14px;border:1px solid var(--line);border-radius:999px;font-weight:600;font-size:14px}
.rp-voice-pill:hover{border-color:var(--navy)}
.rp-dot{width:9px;height:9px;border-radius:50%;background:#C3CAD6}
.rp-dot.is-ok{background:#1FA45B}

/* layout */
.rp-shell{display:grid;grid-template-columns:276px minmax(0,1fr) 350px;gap:20px;padding:20px 24px 28px;max-width:1640px;margin:0 auto;align-items:start}
.rp-side,.rp-right{display:flex;flex-direction:column;gap:16px;position:sticky;top:96px;max-height:calc(100vh - 110px);overflow:auto}
.rp-card{background:#fff;border-radius:14px;padding:18px;border:1px solid var(--line)}
.rp-card-title{font-size:22px;margin-bottom:12px}
.rp-card-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.rp-card-head .rp-card-title{margin:0}

/* modes */
.rp-modes{display:flex;flex-direction:column;gap:8px}
.rp-mode{display:flex;gap:12px;align-items:flex-start;text-align:left;padding:12px;border-radius:10px;border:1.5px solid var(--line);width:100%}
.rp-mode:hover{border-color:#B8C0CC}
.rp-mode.is-on{border-color:var(--red);background:#FFF5F6}
.rp-mode b{display:block;font-size:19px;line-height:1.1}
.rp-mode-icon{flex:none;width:34px;height:34px;border-radius:8px;background:var(--navy);color:#fff;display:grid;place-items:center}
.rp-mode.is-on .rp-mode-icon{background:var(--red)}

/* teams */
.rp-add{display:flex;align-items:center;gap:4px;font-weight:600;font-size:14px;color:var(--red);padding:4px 8px;border-radius:6px}
.rp-add:hover{background:#FFF0F2}
.rp-teams{display:flex;flex-direction:column;gap:4px}
.rp-team{display:flex;align-items:center;border-radius:10px;border:1.5px solid transparent}
.rp-team.is-on{border-color:var(--red);background:#FFF5F6}
.rp-team-main{flex:1;display:flex;align-items:center;gap:10px;padding:8px;text-align:left;min-width:0}
.rp-team-main b{display:block;font-size:18px;line-height:1.1}
.rp-team:hover:not(.is-on){background:#F6F7F9}
.rp-logo-fallback{display:grid;place-items:center;border-radius:50%;background:var(--navy);color:#fff;font-family:'Barlow Condensed',sans-serif;font-weight:700;flex:none}
.rp-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:8px;color:var(--mute);flex:none}
.rp-icon:hover{background:#EEF0F4;color:var(--navy)}
.rp-boxed{border:1px solid var(--line);width:38px;height:38px;background:#fff}

/* main */
.rp-main{display:flex;flex-direction:column;gap:14px;min-width:0}
.rp-main-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap}
.rp-title{font-size:44px;line-height:1;font-weight:800}
.rp-dates{display:flex;align-items:center;gap:8px}
.rp-date{height:38px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:#fff;font:inherit;color:var(--navy)}
.rp-ghost{display:inline-flex;align-items:center;gap:6px;height:38px;padding:0 14px;border:1px solid var(--line);border-radius:8px;background:#fff!important;font-weight:600;font-size:14px}
.rp-ghost:hover{border-color:var(--navy)}
.rp-callout{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid var(--line);border-left:4px solid var(--red);border-radius:10px;padding:12px 16px}
.rp-selbar{display:flex;justify-content:space-between;align-items:center}
.rp-link{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:14px;color:var(--red);margin-left:14px;padding:4px 0}
.rp-link:first-child{margin-left:0}
.rp-link:hover{text-decoration:underline}
.rp-group-title{font-size:26px;margin:6px 0 10px}
.rp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:14px}

/* hero scoreboard (Concept B) */
.rp-hero{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;display:flex;flex-direction:column;gap:16px}
.rp-hero-top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}
.rp-hero-sub{margin-top:6px;font-size:14px}
.rp-badges{display:flex;gap:6px;flex-wrap:wrap}
.rp-badge{padding:4px 10px;border-radius:6px;font-size:12px;font-weight:700;color:#fff}
.rp-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.rp-seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:3px;background:#F6F7F9}
.rp-seg button{padding:6px 14px;border-radius:7px;font-weight:600;font-size:14px;color:var(--mute)}
.rp-seg button.is-on{background:#fff;color:var(--navy);box-shadow:0 1px 2px rgba(10,22,40,.15)}
.rp-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:10px}
.rp-tile{display:flex;flex-direction:column;gap:10px;text-align:left;border:1.5px solid var(--line);border-radius:12px;padding:12px 14px;background:#fff;min-height:112px}
.rp-tile:hover{border-color:#B8C0CC;background:#FAFBFC}
.rp-tile.is-on{border-color:var(--red);background:#FFF5F6}
.rp-tile-top{display:flex;justify-content:space-between;align-items:center;width:100%;font-size:12px;font-weight:600;color:var(--mute)}
.rp-tile-top .is-live{color:var(--red-d)}
.rp-tile-check{width:18px;height:18px;border-radius:5px;background:var(--red);color:#fff;display:grid;place-items:center}
.rp-tile-match{display:flex;align-items:center;justify-content:space-between;width:100%;gap:6px}
.rp-tile-team{display:flex;flex-direction:column;align-items:center;gap:3px;flex:1;min-width:0}
.rp-tile-abbr{font-size:20px;line-height:1;display:inline-flex;align-items:center;gap:4px}
.rp-tile-score{font-size:32px;line-height:1;font-weight:800}
.rp-tile-team.is-dim .rp-tile-abbr,.rp-tile-team.is-dim .rp-tile-score{color:#8791A2}
.rp-tile-sep{color:var(--mute);font-size:13px;font-weight:600}
.rp-bar-btns{display:flex;gap:10px;flex-wrap:wrap}
.rp-ghost-lg{height:52px;padding:0 18px}

/* game card */
.rp-game{background:#fff;border-radius:14px;padding:14px 16px 12px;border:1.5px solid var(--line);display:flex;flex-direction:column;gap:6px}
.rp-game.is-on{border-color:var(--navy);box-shadow:0 0 0 1px var(--navy)}
.rp-game-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:2px}
.rp-chip{font-size:12.5px;font-weight:600;padding:3px 9px;border-radius:5px}
.rp-chip-final{background:var(--navy);color:#fff}
.rp-chip-live{background:#FFE9EC;color:var(--red-d);display:inline-flex;align-items:center;gap:6px}
.rp-chip-live i{width:7px;height:7px;border-radius:50%;background:var(--red)}
.rp-chip-sched{background:#EEF0F4;color:var(--mute)}
.rp-check{width:24px;height:24px;border-radius:7px;border:2px solid #B8C0CC;display:grid;place-items:center;color:#fff;background:#fff}
.rp-check.is-on{background:var(--red);border-color:var(--red)}
.rp-row{display:flex;align-items:center;gap:12px;padding:3px 0}
.rp-row-name{flex:1;min-width:0}
.rp-row-title{display:flex;align-items:center;font-size:22px;line-height:1.05;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rp-row-title.is-dim,.rp-score.is-dim{color:#8791A2}
.rp-score{font-size:36px;font-weight:800;min-width:44px;text-align:right;line-height:1}
.rp-game-note{border-top:1px solid var(--line);padding-top:8px;margin-top:4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.rp-skel{min-height:140px;background:linear-gradient(90deg,#fff,#F4F6F9,#fff);background-size:200% 100%;animation:rp-sh 1.4s linear infinite}
@keyframes rp-sh{to{background-position:-200% 0}}
.rp-empty{background:#fff;border:1px dashed #C3CAD6;border-radius:14px;padding:36px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:8px}
.rp-empty img{height:110px;margin-bottom:6px}
.rp-empty h3{font-size:28px}
.rp-empty p{max-width:430px;color:var(--mute)}

/* generate bar */
.rp-bar{position:sticky;bottom:16px;z-index:5;background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px 16px;box-shadow:0 8px 28px rgba(10,22,40,.14);display:flex;flex-direction:column;gap:12px;margin-top:6px}
.rp-bar-row{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.rp-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-width:230px;height:52px;padding:0 24px;border-radius:12px;background:var(--red)!important;color:#fff;font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:22px}
.rp-primary:hover:not(:disabled){background:var(--red-d)!important}
.rp-primary:disabled{background:#D5DAE2!important;color:#7C8696}
.rp-primary.is-busy:disabled{background:var(--navy)!important;color:#fff}
.rp-primary-sm{height:40px;padding:0 18px;border-radius:9px;background:var(--red)!important;color:#fff;font-weight:600}
.rp-primary-sm:hover:not(:disabled){background:var(--red-d)!important}
.rp-primary-sm:disabled{opacity:.6}
.rp-steps{display:flex;gap:18px;flex-wrap:wrap}
.rp-steps li{display:flex;align-items:center;gap:8px;font-weight:600;color:#8791A2;font-size:14px}
.rp-steps li.is-now{color:var(--navy)}
.rp-steps li.is-done{color:#1FA45B}
.rp-step-dot{width:20px;height:20px;border-radius:50%;border:2px solid #C3CAD6;display:grid;place-items:center}
.is-now .rp-step-dot{border-color:var(--red);color:var(--red)}
.is-done .rp-step-dot{background:#1FA45B;border-color:#1FA45B;color:#fff}
.rp-spin{animation:rp-spin 1s linear infinite}
@keyframes rp-spin{to{transform:rotate(360deg)}}
.rp-note{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;padding:10px 12px;border-radius:9px;font-size:14px}
.rp-note.is-warn{background:#FFF6E0;color:#5C4300}
.rp-note.is-error{background:#FFE9EC;color:#8E1020}

/* player */
.rp-idle{text-align:center;color:var(--mute);display:flex;flex-direction:column;align-items:center;gap:10px;padding:6px 0}
.rp-idle img{width:200px;max-width:100%}
.rp-np-head{margin-bottom:14px}
.rp-np-logos{display:flex;gap:6px;margin-bottom:8px}
.rp-np-title{font-size:28px;line-height:1.05;font-weight:800}
.rp-wave{display:flex;align-items:center;gap:2px;height:84px;cursor:pointer;padding:4px 0}
.rp-wave span{flex:1;border-radius:2px;min-height:4px}
.rp-times{display:flex;justify-content:space-between;font-size:13px;color:var(--mute);font-variant-numeric:tabular-nums;margin:2px 0 10px}
.rp-ctrls{display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:12px}
.rp-play{width:60px;height:60px;border-radius:50%;background:var(--red)!important;display:grid;place-items:center}
.rp-play:hover{background:var(--red-d)!important}
.rp-noaudio{display:flex;flex-direction:column;gap:10px;align-items:flex-start;margin-bottom:10px}
.rp-script{margin-top:10px;max-height:260px;overflow:auto;white-space:pre-wrap;font-size:14px;line-height:1.55;padding:12px;background:#F6F7F9;border-radius:10px}
.rp-eps{display:flex;flex-direction:column;gap:2px}
.rp-eps li{display:flex;align-items:center;border-radius:10px}
.rp-eps li.is-on{background:#FFF5F6}
.rp-ep-main{flex:1;display:flex;gap:12px;align-items:center;padding:8px;text-align:left;min-width:0}
.rp-ep-main b{display:block;font-size:18px;line-height:1.1}
.rp-ep-play{flex:none;width:32px;height:32px;border-radius:50%;background:var(--navy);display:grid;place-items:center}
.rp-eps li:hover:not(.is-on){background:#F6F7F9}

/* modals */
.rp-scrim{position:fixed;inset:0;background:rgba(10,22,40,.5);display:grid;place-items:center;z-index:50;padding:16px}
.rp-modal{background:#fff;border-radius:16px;padding:22px;width:440px;max-width:100%;max-height:90vh;overflow:auto}
.rp-modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.rp-modal-foot{display:flex;justify-content:flex-end;gap:10px;margin-top:8px}
.rp-field{display:flex;flex-direction:column;gap:6px;font-weight:600;margin-bottom:14px}
.rp-field input,.rp-field select,.rp-search input{height:42px;padding:0 12px;border:1px solid #C3CAD6;border-radius:9px;font:inherit;font-weight:400;background:#fff;color:var(--navy)}
.rp-search{display:flex;align-items:center;gap:8px;border:1px solid #C3CAD6;border-radius:9px;padding-left:12px;margin-bottom:10px}
.rp-search input{border:0;flex:1;outline-offset:0}
.rp-pills{display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap}
.rp-pill{padding:6px 14px;border-radius:999px;border:1px solid var(--line);font-weight:600;font-size:14px}
.rp-pill.is-on{background:var(--navy);color:#fff;border-color:var(--navy)}
.rp-addlist{max-height:340px;overflow:auto;border:1px solid var(--line);border-radius:10px}
.rp-addlist button{display:flex;align-items:center;gap:10px;width:100%;padding:8px 12px;text-align:left}
.rp-addlist button b{font-size:19px;flex:1}
.rp-addlist button:hover{background:#F6F7F9}

/* responsive */
@media (max-width:1240px){
  .rp-shell{grid-template-columns:260px minmax(0,1fr)}
  .rp-right{grid-column:1 / -1;position:static;max-height:none;display:grid;grid-template-columns:1fr 1fr;align-items:start}
  .rp-tagline{display:none}
}
@media (max-width:900px){
  .rp-head{flex-wrap:wrap;gap:6px 14px;padding:8px 14px}
  .rp-tabs{order:3;flex-basis:100%;justify-content:flex-start;overflow-x:auto;flex-wrap:nowrap}
  .rp-tab{font-size:19px;white-space:nowrap}
  .rp-voice-pill{margin-left:auto}
  .rp-shell{grid-template-columns:1fr;padding:14px}
  .rp-side,.rp-right{position:static;max-height:none}
  .rp-right{display:flex}
  .rp-title{font-size:36px}
  .rp-primary{width:100%}
}
@media (prefers-reduced-motion:reduce){.rp-skel,.rp-spin{animation:none}}
`;
